package com.skyclone.mod.bank;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * The bank module's data tables, read from {@code data/bank/*.json} (generated by
 * {@code tools/gen/bank/gen_bank.py}). Pure: takes a resource opener, so unit tests read the same files.
 */
public final class BankCatalog {

    /** One Community Shop bits offer. {@code item} is preferred; {@code alternatives} are tried in order. */
    public static final class BitsOffer {
        public String item;
        public List<String> alternatives = new ArrayList<>();
        public long bits;
        public String category;
    }

    public static final class UpgradeTier {
        public int tier;
        public String label;
        public double value;
        public int gems;
        public double hours;
    }

    /** A Community Shop profile/account upgrade with timed construction. */
    public static final class Upgrade {
        public String id;
        /** "profile" (shared by the co-op) or "account" (this member). */
        public String scope;
        public String name;
        public String unit;
        public String note;
        public List<UpgradeTier> tiers = new ArrayList<>();

        public boolean profileScope() { return "profile".equals(scope); }
        public UpgradeTier tier(int t) { return t >= 1 && t <= tiers.size() ? tiers.get(t - 1) : null; }
        public int maxTier() { return tiers.size(); }
    }

    public final List<BankMath.Tier> tiers;
    public final List<BankMath.Band> bands;
    public final List<BankMath.FameRank> fame;
    public final List<BitsOffer> bitsShop;
    public final Map<String, Upgrade> upgrades;
    public final Map<String, String> npcSkins;

    private BankCatalog(List<BankMath.Tier> tiers, List<BankMath.Band> bands, List<BankMath.FameRank> fame,
                        List<BitsOffer> bitsShop, Map<String, Upgrade> upgrades, Map<String, String> npcSkins) {
        this.tiers = tiers;
        this.bands = bands;
        this.fame = fame;
        this.bitsShop = bitsShop;
        this.upgrades = upgrades;
        this.npcSkins = npcSkins;
    }

    private static final Gson GSON = new Gson();

    /** {@code open} returns the stream of {@code data/bank/<file>} or null. */
    public static BankCatalog load(Function<String, InputStream> open) {
        List<BankMath.Tier> tiers = read(open, "tiers.json", new TypeToken<List<BankMath.Tier>>() {}.getType());
        tiers.sort(Comparator.comparingInt(t -> t.index));
        List<BankMath.Band> bands = read(open, "interest.json", new TypeToken<List<BankMath.Band>>() {}.getType());
        List<BankMath.FameRank> fame = read(open, "fame.json", new TypeToken<List<BankMath.FameRank>>() {}.getType());
        fame.sort(Comparator.comparingLong(f -> f.fame));
        List<BitsOffer> shop = read(open, "bits_shop.json", new TypeToken<List<BitsOffer>>() {}.getType());
        List<Upgrade> ups = read(open, "upgrades.json", new TypeToken<List<Upgrade>>() {}.getType());
        Map<String, Upgrade> upMap = new LinkedHashMap<>();
        for (Upgrade u : ups) upMap.put(u.id, u);
        Map<String, String> skins = read(open, "npcs.json", new TypeToken<Map<String, String>>() {}.getType());
        return new BankCatalog(tiers, bands, fame, shop, upMap, skins == null ? Map.of() : skins);
    }

    private static <T> T read(Function<String, InputStream> open, String file, Type type) {
        InputStream in = open.apply(file);
        if (in == null) throw new IllegalStateException("missing data/bank/" + file);
        try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
            T v = GSON.fromJson(r, type);
            if (v == null) throw new IllegalStateException("empty data/bank/" + file);
            return v;
        } catch (java.io.IOException e) {
            throw new IllegalStateException("cannot read data/bank/" + file + ": " + e.getMessage(), e);
        }
    }

    public BankMath.Tier tier(int index) {
        if (tiers.isEmpty()) return null;
        return tiers.get(Math.max(0, Math.min(index, tiers.size() - 1)));
    }

    public int maxTier() { return tiers.size() - 1; }

    public BankMath.FameRank fameRank(long fameValue) {
        if (fame.isEmpty()) return null;
        return fame.get(BankMath.fameRank(fameValue, fame));
    }
}
